using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RepresentativeContactTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Other=new("org:oda"),Old=new("person:shingen"),Opponent=new("person:nobunaga"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static readonly Lazy<ContractWorld> Ready=new(Create);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var n=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>n);}}
    static long Arrival(WorldSession s,string message)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==message)).ReadyAt;
    static ContractWorld Create()=>CreateCore(true);
    static ContractWorld CreateCore(bool read){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy,trucePolicy:TruceNegotiations.Policy));Good(s.NegotiateTruce(new(new("request:confirmation-original-proposal"),TruceAction.Propose,Owner,Other,Days:30),Old,s.Revision));var offer=s.DiagnosticSnapshot().Truces!.Papers.Single();At(s,Arrival(s,offer.Message)+1);var accept=s.DiagnosticSnapshot().Truces!.Papers.Single(p=>p.Input.Action==TruceAction.Accept);At(s,Arrival(s,accept.Message));var succession=new EntityId("request:confirmation-succession");Good(s.ManageHouseSuccession(new(succession,HouseSuccessionAction.Nominate,Owner,Heir),Old,s.Revision));Good(s.ManageHouseSuccession(new(new("request:confirmation-head-consent"),HouseSuccessionAction.Confirm,Owner,Original:succession),Old,s.Revision));At(s,s.Seconds+1);Good(s.Open(Old,new(accept.Message),s.Revision));if(read)Good(s.ReadInheritedTruce(new(new("request:confirmation-inherited-read"),Owner,accept.Input.Id),Old,s.Revision));s.SetPaused(true);return s.DiagnosticSnapshot();}
    static WorldSession Start()=>new(ContractJson.Copy(Ready.Value));
    static EntityId Acceptance(WorldSession s)=>s.DiagnosticSnapshot().Truces!.Formations.Single().Acceptance;
    static TruceConfirmationInput Input(WorldSession s,TruceConfirmationAction action=TruceConfirmationAction.InquireRepresentative,string? original=null)=>new(new("request:confirmation-test/"+s.Revision),action,Owner,Acceptance(s),original);
    static TruceConfirmationPaper Send(WorldSession s){Good(s.SendTruceConfirmation(Input(s),Old,s.Revision));return s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.RepresentativeInquiry);}
    static TruceConfirmationPaper Receipt(WorldSession s)=>s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.Receipt);
    static TruceConfirmationPaper FailAndReport(WorldSession s,TruceConfirmationPaper p,bool open=true){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Id));At(s,Arrival(s,p.Id)+2);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id));At(s,Arrival(s,f.Id)+1);var notices=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Where(n=>n.Kind==TruceConfirmationKind.FailureNotice&&n.Related==p.Id).ToArray();Assert.True(notices.Length==1,System.Text.Json.JsonSerializer.Serialize(new{Time=s.Seconds,Confirm=s.DiagnosticSnapshot().TruceConfirmations,Attempts=s.DiagnosticSnapshot().Messaging.Attempts,Known=s.DiagnosticSnapshot().Messaging.Knowledge}));var notice=notices.Single();At(s,Arrival(s,notice.Id)+1);if(open)Good(s.Open(Old,new(notice.Id),s.Revision));return notice;}

    static RepresentativeObservation K(WorldSession s,EntityId actor,EntityId owner)=>RepresentativeKnowledge.Known(s.DiagnosticSnapshot(),actor,owner)!;
    static TruceConfirmationPaper Answer(WorldSession s)=>s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation);
    static void ReturnToOld(WorldSession s){var b=s.HouseholdServiceView()!.Releases.Single(b=>b.Subject==Heir);Good(s.ManageHouseholdService(new(new("request:rep-release"),HouseholdServiceAction.Release,Owner,b.Other,b.Source),Old,s.Revision));Good(s.ManageHouseholdService(new(new("request:rep-pledge"),HouseholdServiceAction.Pledge,Owner,Heir),Old,s.Revision));var id=new EntityId("request:rep-second-succession");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Old),Old,s.Revision));Good(s.ManageHouseSuccession(new(new("request:rep-second-consent"),HouseSuccessionAction.Confirm,Owner,Original:id),Old,s.Revision));At(s,s.Seconds+1);}
    [Fact]public void ForeignPrivateSuccessionDoesNotChangeTheObserversKnownRepresentative(){var s=Start();Assert.Equal(Heir,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal(Old,K(s,Opponent,Owner).Person);Assert.Equal(Heir,K(s,Old,Owner).Person);Assert.Equal(Heir,K(s,Heir,Owner).Person);Assert.Equal("現地立会",K(s,Old,Owner).Route);}
    [Fact]public void InquiryUsesSignersKnownAddressAndPreservesTheOriginalTerms(){var s=Start();var before=s.DiagnosticSnapshot();var known=K(s,Heir,Other);var p=Send(s);Assert.Equal(known.Person,p.Recipient);Assert.Equal(known.Home,p.Address);Assert.Equal(known.ObservedAt,p.ObservedAt);Assert.Equal(known.Source,p.Evidence);Assert.Equal(Heir,p.Sender);Assert.Equal(Old,p.Requester);Assert.Equal(before.Truces!.Formations.Single().Terms,p.Terms);Assert.Equal(ContractJson.Write(before.Truces),ContractJson.Write(s.DiagnosticSnapshot().Truces));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void UnreceivedSignatureCannotUpdateForeignKnowledge(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id)-1);Assert.Equal(Old,K(s,Opponent,Owner).Person);Assert.Equal(0,K(s,Opponent,Owner).ObservedAt);}
    [Fact]public void PhysicalInquiryThenDirectHeadReplyThenRequesterReceiptAreSeparateJourneys(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));Assert.Equal(Heir,K(s,Opponent,Owner).Person);Assert.Equal(p.Authority!.At,K(s,Opponent,Owner).ObservedAt);var a=Answer(s);Assert.Equal(Opponent,a.Sender);Assert.Equal(Heir,a.Recipient);Assert.Equal(p.Authority.Home,a.Address);Assert.Equal(p.Terms,a.Terms);Assert.Equal(p.Id,a.Related);Assert.Empty(s.TruceConfirmationView().Reports);At(s,Arrival(s,a.Id));var receipt=Receipt(s);Assert.Equal(Heir,receipt.Sender);Assert.Equal(Old,receipt.Recipient);Assert.Equal(a.Id,receipt.Related);Assert.Equal(p.Terms,receipt.Terms);At(s,Arrival(s,receipt.Id));Assert.Empty(s.TruceConfirmationView().Reports);Good(s.Open(Old,new(receipt.Id),s.Revision));Assert.Single(s.TruceConfirmationView().Reports);Assert.Equal(p.Terms,s.DiagnosticSnapshot().Truces!.Formations.Single().Terms);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void OpeningAndSignatureHaveSeparateHistoricalPrefixes(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var w=s.DiagnosticSnapshot();var o=w.TruceConfirmations!.Openings.Single(o=>o.Message==p.Id);Assert.Equal(Old,RepresentativeKnowledge.Known(w,Opponent,Owner,o.At,o.Revision-1)!.Person);Assert.Equal(Heir,RepresentativeKnowledge.Known(w,Opponent,Owner,o.At,o.Revision)!.Person);Assert.Equal(p.Authority!.At,K(s,Opponent,Owner).ObservedAt);Assert.Equal(o.At,K(s,Opponent,Owner).LearnedAt);}
    [Fact]public void UnopenedReceiptCannotLeakItsSignedAuthority(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var a=Answer(s);At(s,Arrival(s,a.Id));var receipt=Receipt(s);At(s,Arrival(s,receipt.Id));Assert.DoesNotContain(RepresentativeKnowledge.Observations(s.DiagnosticSnapshot(),Old),o=>o.Source==receipt.Id);Good(s.Open(Old,new(receipt.Id),s.Revision));Assert.Contains(RepresentativeKnowledge.Observations(s.DiagnosticSnapshot(),Old),o=>o.Source==receipt.Id);}
    [Fact]public void LostInquiryNeedsPersonallyOpenedFailureBeforeSameAddressRetry(){var s=Start();var p=Send(s);var n=FailAndReport(s,p,false);Assert.Equal(Old,K(s,Opponent,Owner).Person);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);Good(s.Open(Old,new(n.Id),s.Revision));Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last();Assert.Equal(p.Recipient,copy.Recipient);Assert.Equal(p.Address,copy.Address);Assert.Equal(p.ObservedAt,copy.ObservedAt);Assert.Equal(p.Evidence,copy.Evidence);At(s,Arrival(s,copy.Id));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void RepeatedInquiryAndDuplicateIdsCannotCreateAnotherRoot(){var s=Start();var i=Input(s);Good(s.SendTruceConfirmation(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.SendTruceConfirmation(i,Old,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.SendTruceConfirmation(i with{Owner=Other},Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers);}
    [Fact]public void InquiryDoesNotPretendThePlayerControlsItsNpcSigner(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Heir,s.Revision).Code);Send(s);Assert.Equal(Old,s.PlayerControl);Assert.Equal(Heir,s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single().Authority!.Issuer);}
    [Fact]public void ExpiredTruceCannotBeRenewedByInquiry(){var s=Start();At(s,s.DiagnosticSnapshot().Truces!.Formations.Single().Terms.Until);Assert.Empty(TruceConfirmations.RepresentativeCandidates(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);}
    [Fact]public void SuccessiveLocalSuccessionLeavesTheForeignMemoryUntilTheNewSignatureArrives(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));Assert.Equal(Heir,K(s,Opponent,Owner).Person);ReturnToOld(s);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal(Heir,K(s,Opponent,Owner).Person);Assert.Equal(Old,K(s,Old,Owner).Person);Good(s.SendTruceConfirmation(Input(s),Old,s.Revision));var q=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.RepresentativeInquiry);Assert.Equal(Old,q.Sender);At(s,Arrival(s,q.Id));Assert.Equal(Old,K(s,Opponent,Owner).Person);Assert.Equal(2,s.DiagnosticSnapshot().TruceConfirmations!.Papers.Count(p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ReplyAddressRemainsTheOriginalSignerAfterAnotherSuccession(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var a=Answer(s);ReturnToOld(s);At(s,Arrival(s,a.Id));Assert.Equal(Heir,a.Recipient);Assert.DoesNotContain(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.Receipt&&q.Root==p.Id);Assert.DoesNotContain(RepresentativeKnowledge.Observations(s.DiagnosticSnapshot(),Old),o=>o.Source==a.Id);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LateOldSignatureDoesNotUndoANewerObservedRepresentative(){var s=Start();var i=Input(s,TruceConfirmationAction.Send);Good(s.SendTruceConfirmation(i,Old,s.Revision));var old=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single();FailAndReport(s,old);ReturnToOld(s);Good(s.SendTruceConfirmation(Input(s),Old,s.Revision));var q=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.RepresentativeInquiry);At(s,Arrival(s,q.Id));var known=K(s,Opponent,Owner);Assert.Equal(Old,known.Person);s.DiagnosticRecoverLocalCourier(old.Id,1);At(s,s.Seconds+1);Assert.Equal(known,K(s,Opponent,Owner));Assert.Contains(RepresentativeKnowledge.Observations(s.DiagnosticSnapshot(),Opponent),o=>o.Source==old.Id&&o.Person==Heir);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(false)][InlineData(true)]public void RecoveredOriginalAndCopyCauseOneResponseAndOneReceipt(bool originalFirst){var s=Start();var p=Send(s);FailAndReport(s,p);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.RepresentativeInquiry);if(!originalFirst)At(s,Arrival(s,copy.Id));s.DiagnosticRecoverLocalCourier(p.Id,1);At(s,s.Seconds+1);if(originalFirst)At(s,Arrival(s,copy.Id));var a=Answer(s);At(s,Arrival(s,a.Id));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation);Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.Receipt);Assert.Single(s.DiagnosticSnapshot().Truces!.Formations);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void FailedDirectReplyCopiesKeepOldSignatureTimeAndAddress(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var a=Answer(s);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,a.Id));At(s,Arrival(s,a.Id));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.RepresentativeConfirmation);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(x=>x.Id==m.Body&&x.MessageId==a.Id));At(s,Arrival(s,f.Id));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(q=>q.Kind==TruceConfirmationKind.RepresentativeConfirmation);Assert.Equal(a.Id,copy.CopyOf);Assert.Equal(a.Authority,copy.Authority);Assert.Equal(a.ObservedAt,copy.ObservedAt);Assert.Equal(a.Evidence,copy.Evidence);Assert.Equal(a.Address,copy.Address);At(s,Arrival(s,copy.Id));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.Receipt);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedInquiryTargetDateSourceAndSignerCannotLoad(int n){var s=Start();Send(s);var w=s.DiagnosticSnapshot();var p=w.TruceConfirmations!.Papers.Single();w.TruceConfirmations.Papers[0]=n switch{0=>p with{Recipient=Heir},1=>p with{ObservedAt=123},2=>p with{Evidence="invented"},_=>p with{Sender=Old}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedDirectResponseCannotLoad(int n){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var w=s.DiagnosticSnapshot();var a=w.TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation);var index=Array.IndexOf(w.TruceConfirmations.Papers,a);w.TruceConfirmations.Papers[index]=n switch{0=>a with{Recipient=Old},1=>a with{Terms=a.Terms with{Until=a.Terms.Until+1}},2=>a with{Authority=a.Authority! with{Issuer=Heir}},_=>a with{Evidence="invented"}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void InvalidKnowledgeQueriesAreRejected(int n){var s=Start();var w=s.DiagnosticSnapshot();Assert.Throws<InvalidDataException>(()=>RepresentativeKnowledge.Observations(w,n==0?new("person:absent"):Old,n==1?w.ElapsedSeconds+1:n==2?-1:w.ElapsedSeconds,n==3?w.CommitSequence+1:w.CommitSequence));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)]public void ActualGenerationRecoveryRetainsPersonalEvidenceAndFuture(int phase){var s=Start();TruceConfirmationPaper? p=null;if(phase>0)p=Send(s);if(phase is >=2 and <=5){At(s,Arrival(s,p!.Id));if(phase>=3){var a=Answer(s);At(s,Arrival(s,a.Id));if(phase>=4){var receipt=Receipt(s);At(s,Arrival(s,receipt.Id));if(phase==5)Good(s.Open(Old,new(receipt.Id),s.Revision));}}}if(phase>=6){FailAndReport(s,p!,phase!=6);if(phase>=8){Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p!.Id),Old,s.Revision));if(phase==9){var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.RepresentativeInquiry);At(s,Arrival(s,copy.Id));}}}Save(s,"representative-contact-"+phase);}
    [Fact]public void CurrentPlayerHeadMustOpenAndExplicitlyAcknowledgeTheDirectReply(){var s=Start();ReturnToOld(s);var p=Send(s);Assert.Equal(Old,p.Sender);At(s,Arrival(s,p.Id));var a=Answer(s);Assert.Equal(Old,a.Recipient);At(s,Arrival(s,a.Id));Assert.DoesNotContain(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.Receipt);Assert.DoesNotContain(RepresentativeKnowledge.Observations(s.DiagnosticSnapshot(),Old),o=>o.Source==a.Id);Good(s.Open(Old,new(a.Id),s.Revision));Assert.Contains(a.Id,s.TruceConfirmationView().Acknowledgeable);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Acknowledge,a.Id),Old,s.Revision));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.Receipt);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void InquiryArrivingAfterOriginalExpiryAddsDatedKnowledgeButNoPoliticalReply(){var s=Start();var p=Send(s);FailAndReport(s,p);At(s,p.Terms.Until+1);s.DiagnosticRecoverLocalCourier(p.Id,1);At(s,s.Seconds+1);Assert.Equal(Heir,K(s,Opponent,Owner).Person);Assert.DoesNotContain(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.RepresentativeConfirmation);Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Other,Owner,s.Seconds,s.Revision));Assert.Equal(p.Terms,s.DiagnosticSnapshot().Truces!.Formations.Single().Terms);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LostDirectReplyIsBoundedToThreeCopiesEvenAfterAllFailureReportsArrive(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));for(int n=0;n<3;n++){var a=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.RepresentativeConfirmation);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,a.Id));At(s,Arrival(s,a.Id));var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(x=>x.Id==m.Body&&x.MessageId==a.Id));At(s,Arrival(s,f.Id));}Assert.Equal(3,s.DiagnosticSnapshot().TruceConfirmations!.Papers.Count(q=>q.Kind==TruceConfirmationKind.RepresentativeConfirmation));Assert.DoesNotContain(s.DiagnosticSnapshot().TruceConfirmations!.Papers,q=>q.Kind==TruceConfirmationKind.Receipt);new WorldSession(s.DiagnosticSnapshot());}
    static void Save(WorldSession s,string name){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"representative-contact-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"representative",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("representative"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));foreach(var actor in new[]{Old,Heir,Opponent})Assert.Equal(ContractJson.Write(RepresentativeKnowledge.Observations(w,actor)),ContractJson.Write(RepresentativeKnowledge.Observations(b.DiagnosticSnapshot(),actor)));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var x in new[]{s,b})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
}
